WITH long_format AS (SELECT id, store_id, metric, reading FROM (SELECT id, store_id, discount, amount, shipping_fee FROM orders) src UNPIVOT INCLUDE NULLS (reading FOR metric IN (discount AS DISCOUNT, amount AS AMOUNT_VAL, shipping_fee AS SHIPPING_FEE_VAL))) SELECT CASE WHEN reading >= 87 THEN 'HIGH' ELSE 'LOW' END AS reading_tier, COUNT(*) FILTER (WHERE metric = 'DISCOUNT') AS discount_rows, ROUND(SUM(reading) / NULLIF(COUNT(CASE WHEN metric = 'AMOUNT_VAL' THEN 1 END), 0), 2) AS reading_per_amount_val, COUNT(*) FILTER (WHERE metric = 'SHIPPING_FEE_VAL') AS shipping_fee_val_rows FROM long_format GROUP BY reading_tier;
